149	    /// It retrieves the severity based on the `code` of the rule and the current configuration.
150	    ///
151	    /// The code of the has the following pattern: `{group}/{rule_name}`.
152	    ///
153	    /// It returns [None] if the `code` doesn't match any rule.
154	    pub fn get_severity_from_rule_code(
155	        &self,
156	        code: &Category,
157	    ) -> Option<biome_diagnostics::Severity> {
158	        let rules = self.linter.rules.as_ref();
159	        if let Some(rules) = rules {
160	            rules.get_severity_from_code(code)
161	        } else {
162	            None
163	        }
164	    }
165	
166	    /// Returns rules taking overrides into account.
167	    pub fn as_rules(&self, path: &Path) -> Option<Cow<Rules>> {
168	        let mut result = self.linter.rules.as_ref().map(Cow::Borrowed);
169	        let overrides = &self.override_settings;
170	        for pattern in overrides.patterns.iter() {
171	            let excluded = pattern.exclude.matches_path(path);
172	            if !excluded && !pattern.include.is_empty() && pattern.include.matches_path(path) {
173	                let pattern_rules = pattern.linter.rules.as_ref();
174	                if let Some(pattern_rules) = pattern_rules {
175	                    result = if let Some(mut result) = result.take() {
176	                        // Override rules
177	                        result.to_mut().merge_with(pattern_rules.clone());
178	                        Some(result)
179	                    } else {
180	                        Some(Cow::Borrowed(pattern_rules))
181	                    };
182	                }
183	            }
184	        }
185	        result
186	    }
187	}
